-- auto-apply
-- Writing flow content (2026-10): one reviewed content pack per weekly
-- topic + level (format, model sentences, patterns, sentence frames,
-- checklist, model answer). Read by everyone, written by admin only.
-- Shared, so topic material is made once — not per learner per session.
create table if not exists public.writing_topic_content (
  topic_ko   text not null,
  level      text not null,
  content    jsonb not null,
  reviewed   boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (topic_ko, level)
);
alter table public.writing_topic_content enable row level security;
drop policy if exists wtc_read on public.writing_topic_content;
create policy wtc_read on public.writing_topic_content for select using (true);
drop policy if exists wtc_admin_write on public.writing_topic_content;
create policy wtc_admin_write on public.writing_topic_content for all using (public.is_admin_email()) with check (public.is_admin_email());
grant select on public.writing_topic_content to anon, authenticated;
grant insert, update, delete on public.writing_topic_content to authenticated;

insert into public.writing_topic_content (topic_ko, level, content, reviewed) values ('책 읽는 것을 좋아해요?', 'Starter', '{"format": {"label": "Short answer · 2–4 sentences", "hint": "Say if you like reading and what you read."}, "min_sentences": 2, "models": [{"ko": "네, 저는 책 읽는 것을 좋아해요.", "en": "Yes, I like reading books.", "hl": ["을 좋아해요"]}, {"ko": "저는 만화책을 자주 읽어요.", "en": "I often read comics.", "hl": ["자주"]}, {"ko": "주말에 카페에서 책을 읽어요.", "en": "On weekends I read at a café.", "hl": ["에서"]}], "patterns": [{"name": "~을/를 좋아해요", "exp": "Say what you like.", "ex_ko": "저는 소설을 좋아해요.", "ex_en": "I like novels.", "match": ["좋아해요", "좋아합니다"]}, {"name": "~에서", "exp": "Where you do something.", "ex_ko": "도서관에서 책을 읽어요.", "ex_en": "I read at the library.", "match": ["에서"]}, {"name": "자주 / 가끔", "exp": "Often / sometimes.", "ex_ko": "저는 가끔 시를 읽어요.", "ex_en": "I sometimes read poems.", "match": ["자주", "가끔", "매일"]}], "frames": [{"parts": ["저는 ", {"slot": true, "options": ["책 읽는 것", "소설", "만화책", "잡지"], "josa": "을/를", "ph": "…"}, " 좋아해요."], "en": "I like ___."}, {"parts": ["저는 ", {"slot": true, "options": ["자주", "가끔", "매일"], "josa": null, "ph": "…"}, " 책을 읽어요."], "en": "I read books ___."}, {"parts": [{"slot": true, "options": ["집", "카페", "도서관", "지하철"], "josa": "에서", "ph": "…"}, " 책을 읽어요."], "en": "I read books at/on ___."}], "words": ["책", "읽", "좋아", "소설", "만화책", "도서관", "자주", "가끔"], "checklist": [{"label": "Say if you like reading", "any": ["좋아해요", "좋아하", "싫어", "안 좋아"]}, {"label": "Say where or when you read", "any": ["에서", "주말", "저녁", "아침", "자기 전", "매일"]}, {"label": "Use ~을/를 좋아해요", "any": ["좋아해요", "좋아합니다"], "optional": true}], "model_answer": "네, 저는 책 읽는 것을 좋아해요. 특히 만화책을 자주 읽어요. 주말에는 카페에서 책을 읽어요. 커피를 마시면서 읽으면 정말 좋아요."}'::jsonb, true)
  on conflict (topic_ko, level) do update set content = excluded.content, reviewed = true, updated_at = now();
insert into public.writing_topic_content (topic_ko, level, content, reviewed) values ('내 취미 하나', 'Starter', '{"format": {"label": "Short answer · 2–4 sentences", "hint": "Name one hobby, when you do it, and how it feels."}, "min_sentences": 2, "models": [{"ko": "제 취미는 요리예요.", "en": "My hobby is cooking.", "hl": ["예요"]}, {"ko": "주말에 친구하고 같이 요리해요.", "en": "On weekends I cook with a friend.", "hl": ["하고 같이"]}, {"ko": "요리는 정말 재미있어요.", "en": "Cooking is really fun.", "hl": ["재미있어요"]}], "patterns": [{"name": "N은/는 N이에요/예요", "exp": "Say what something is.", "ex_ko": "제 취미는 사진이에요.", "ex_en": "My hobby is photography.", "match": ["이에요", "예요"]}, {"name": "N하고 같이", "exp": "Together with someone.", "ex_ko": "동생하고 같이 운동해요.", "ex_en": "I exercise with my younger sibling.", "match": ["하고 같이", "랑 같이", "와 같이", "과 같이"]}, {"name": "~아요/어요 (feelings)", "exp": "Say how it feels.", "ex_ko": "운동하면 기분이 좋아요.", "ex_en": "Exercising makes me feel good.", "match": ["재미있어요", "좋아요", "즐거워요", "편해요"]}], "frames": [{"parts": ["제 취미는 ", {"slot": true, "options": ["요리", "운동", "사진", "게임", "노래"], "josa": "이에요/예요", "ph": "…"}, "."], "en": "My hobby is ___."}, {"parts": [{"slot": true, "options": ["주말", "저녁", "퇴근 후"], "josa": "에", "ph": "…"}, " 자주 해요."], "en": "I often do it ___."}, {"parts": ["정말 ", {"slot": true, "options": ["재미있어요", "즐거워요", "편해요"], "josa": null, "ph": "…"}, "."], "en": "It''s really ___."}], "words": ["취미", "주말", "같이", "재미있", "좋아"], "checklist": [{"label": "Name your hobby", "any": ["취미"]}, {"label": "Say when you do it", "any": ["주말", "저녁", "아침", "후에", "때", "매일"]}, {"label": "Say how it feels", "any": ["재미있", "좋아", "즐거", "편해", "신나"]}], "model_answer": "제 취미는 요리예요. 주말에 친구하고 같이 요리해요. 한국 음식을 자주 만들어요. 요리는 정말 재미있어요."}'::jsonb, true)
  on conflict (topic_ko, level) do update set content = excluded.content, reviewed = true, updated_at = now();
insert into public.writing_topic_content (topic_ko, level, content, reviewed) values ('하루 중 가장 좋아하는 시간이 언제예요?', 'Beginner', '{"format": {"label": "Short answer · 3–5 sentences", "hint": "Say which time you like and why — like telling a friend."}, "min_sentences": 3, "models": [{"ko": "저는 아침이 제일 좋아요.", "en": "I like mornings the most.", "hl": ["이 제일 좋아요"]}, {"ko": "아침에는 조용해서 공부가 잘 돼요.", "en": "It''s quiet in the morning, so I can focus.", "hl": ["해서"]}, {"ko": "그리고 커피를 마시면서 하루를 시작해요.", "en": "And I start my day with a coffee.", "hl": ["면서"]}], "patterns": [{"name": "~이/가 제일 좋아요", "exp": "Say what you like most.", "ex_ko": "저는 저녁이 제일 좋아요.", "ex_en": "I like evenings the most.", "match": ["제일 좋아", "가장 좋아"]}, {"name": "~아서/어서", "exp": "Reason → result.", "ex_ko": "날씨가 좋아서 산책했어요.", "ex_en": "The weather was nice, so I took a walk.", "match": ["아서", "어서", "해서", "워서", "러서"]}, {"name": "~(으)면서", "exp": "Two things at once.", "ex_ko": "음악을 들으면서 쉬어요.", "ex_en": "I relax while listening to music.", "match": ["면서"]}], "frames": [{"parts": ["저는 ", {"slot": true, "options": ["아침", "점심시간", "저녁", "밤", "새벽"], "josa": "이/가", "ph": "…"}, " 제일 좋아요."], "en": "I like ___ the most."}, {"parts": ["그때는 ", {"slot": true, "options": ["조용해서", "일이 끝나서", "여유가 있어서", "마음이 편해서"], "josa": null, "ph": "…"}, " 기분이 좋아요."], "en": "I feel good then because ___."}, {"parts": ["보통 ", {"slot": true, "options": ["음악을 들으면서", "커피를 마시면서", "산책하면서", "드라마를 보면서"], "josa": null, "ph": "…"}, " 쉬어요."], "en": "I usually relax while ___."}], "words": ["아침", "저녁", "점심", "밤", "새벽", "제일", "가장", "좋아", "쉬"], "checklist": [{"label": "Say which time you like", "any": ["아침", "점심", "저녁", "밤", "새벽", "오후", "오전"]}, {"label": "Give a reason (~아서/어서)", "any": ["@reason", "니까", "때문에"]}, {"label": "Try ~(으)면서", "any": ["면서"], "optional": true}], "model_answer": "저는 저녁이 제일 좋아요. 저녁에는 일이 끝나서 마음이 편해요. 보통 음악을 들으면서 쉬어요. 가끔 친구를 만나서 같이 저녁을 먹어요."}'::jsonb, true)
  on conflict (topic_ko, level) do update set content = excluded.content, reviewed = true, updated_at = now();
insert into public.writing_topic_content (topic_ko, level, content, reviewed) values ('아침 루틴이 있나요?', 'Beginner', '{"format": {"label": "Short answer · 3–5 sentences", "hint": "Walk through your morning in order."}, "min_sentences": 3, "models": [{"ko": "네, 저는 아침 루틴이 있어요.", "en": "Yes, I have a morning routine.", "hl": []}, {"ko": "일어나서 먼저 물을 한 잔 마셔요.", "en": "After I get up, I first drink a glass of water.", "hl": ["일어나서", "먼저"]}, {"ko": "그다음에 샤워하고 아침을 먹어요.", "en": "Then I shower and eat breakfast.", "hl": ["그다음에", "하고"]}], "patterns": [{"name": "~아서/어서 (then)", "exp": "Do A, then B (connected).", "ex_ko": "일어나서 세수를 해요.", "ex_en": "I get up and wash my face.", "match": ["나서", "어서", "아서", "해서"]}, {"name": "~고", "exp": "Listing actions in order.", "ex_ko": "샤워하고 옷을 입어요.", "ex_en": "I shower and get dressed.", "match": ["고 "]}, {"name": "먼저 / 그다음에", "exp": "First / then.", "ex_ko": "먼저 이를 닦고 그다음에 밥을 먹어요.", "ex_en": "First I brush my teeth, then I eat.", "match": ["먼저", "그다음", "그리고", "마지막으로"]}], "frames": [{"parts": ["저는 보통 아침 ", {"slot": true, "options": ["6시", "7시", "8시", "9시"], "josa": "에", "ph": "…"}, " 일어나요."], "en": "I usually get up at ___."}, {"parts": ["일어나서 먼저 ", {"slot": true, "options": ["물을 한 잔 마셔요", "스트레칭을 해요", "휴대폰을 봐요", "샤워를 해요"], "josa": null, "ph": "…"}, "."], "en": "After I get up, first I ___."}, {"parts": ["그다음에 ", {"slot": true, "options": ["아침을 먹고", "커피를 마시고", "옷을 입고"], "josa": null, "ph": "…"}, " 집에서 나가요."], "en": "Then I ___ and leave home."}], "words": ["아침", "일어나", "먼저", "그다음", "샤워", "루틴"], "checklist": [{"label": "Say when you get up", "any": ["시에", "일어나"]}, {"label": "Describe 2+ steps in order", "any": ["먼저", "그다음", "그리고", "나서", "고 "]}, {"label": "Use ~아서/어서 or ~고", "any": ["@reason", "고 "], "optional": true}], "model_answer": "저는 보통 아침 7시에 일어나요. 일어나서 먼저 물을 한 잔 마셔요. 그다음에 샤워하고 간단하게 아침을 먹어요. 아침 루틴이 있으면 하루가 편해요."}'::jsonb, true)
  on conflict (topic_ko, level) do update set content = excluded.content, reviewed = true, updated_at = now();
insert into public.writing_topic_content (topic_ko, level, content, reviewed) values ('좋아하는 음식점을 추천하고 이유를 설명해 보세요.', 'Intermediate', '{"format": {"label": "Recommendation · 4–6 sentences", "hint": "Where it is, what to order, and why you recommend it."}, "min_sentences": 4, "models": [{"ko": "회사 근처에 있는 작은 칼국수집을 추천하고 싶어요.", "en": "I''d like to recommend a small kalguksu place near my office.", "hl": ["추천하고 싶어요"]}, {"ko": "국물이 진하고 양이 많아서 늘 손님이 많아요.", "en": "The broth is rich and the portions are big, so it''s always busy.", "hl": ["아서"]}, {"ko": "가격도 저렴한 편이라서 부담 없이 갈 수 있어요.", "en": "It''s fairly cheap too, so you can go without worrying.", "hl": ["편이라서"]}], "patterns": [{"name": "~(으)ㄴ/는 편이다", "exp": "Tends to be / fairly.", "ex_ko": "이 집은 음식이 짠 편이에요.", "ex_en": "The food here tends to be salty.", "match": ["편이에요", "편이라서", "편이고", "편입니다"]}, {"name": "~아서/어서 · ~기 때문에", "exp": "Give reasons.", "ex_ko": "분위기가 조용해서 대화하기 좋아요.", "ex_en": "It''s quiet, so it''s good for talking.", "match": ["아서", "어서", "해서", "기 때문에", "라서"]}, {"name": "꼭 ~아/어 보세요", "exp": "Recommend strongly.", "ex_ko": "근처에 가면 꼭 한번 가 보세요.", "ex_en": "If you''re nearby, be sure to try it.", "match": ["보세요", "추천"]}], "frames": [{"parts": [{"slot": true, "options": ["회사 근처에 있는", "집 앞에 있는", "학교 근처에 있는"], "josa": null, "ph": "…"}, " ", {"slot": true, "options": ["칼국수집", "카페", "고깃집", "분식집"], "josa": "을/를", "ph": "…"}, " 추천하고 싶어요."], "en": "I''d like to recommend the ___ ___."}, {"parts": ["이곳은 ", {"slot": true, "options": ["음식이 맛있고", "분위기가 좋고", "가격이 저렴하고"], "josa": null, "ph": "…"}, " ", {"slot": true, "options": ["직원들이 친절해요", "양이 많아요", "조용해요"], "josa": null, "ph": "…"}, "."], "en": "This place ___ and ___."}, {"parts": ["특히 ", {"slot": true, "options": ["김치찌개", "파스타", "비빔밥", "떡볶이"], "josa": "이/가", "ph": "…"}, " 맛있는 편이에요."], "en": "The ___ is especially good."}], "words": ["추천", "근처", "맛있", "분위기", "가격", "편이"], "checklist": [{"label": "Say where the place is", "any": ["근처", "앞에", "역", "동네", "에 있는"]}, {"label": "Give two reasons", "any": ["고 ", "@reason", "기 때문에"]}, {"label": "Recommend it (~아/어 보세요)", "any": ["보세요", "추천"]}], "model_answer": "저는 회사 근처에 있는 작은 칼국수집을 추천하고 싶어요. 이곳은 국물이 진하고 면이 쫄깃해서 늘 손님이 많아요. 가격도 저렴한 편이라서 점심에 부담 없이 갈 수 있어요. 특히 비 오는 날에 먹으면 정말 맛있어요. 근처에 가시면 꼭 한번 드셔 보세요."}'::jsonb, true)
  on conflict (topic_ko, level) do update set content = excluded.content, reviewed = true, updated_at = now();
insert into public.writing_topic_content (topic_ko, level, content, reviewed) values ('처음 먹어봤을 때 놀랐던 음식이 있나요? 어떤 점이 놀라웠어요?', 'Intermediate', '{"format": {"label": "Short story · 4–6 sentences", "hint": "What it was, why it surprised you, how it turned out."}, "min_sentences": 4, "models": [{"ko": "처음 산낙지를 먹었을 때 정말 놀랐어요.", "en": "I was really surprised the first time I ate live octopus.", "hl": ["었을 때"]}, {"ko": "접시 위에서 다리가 계속 움직였거든요.", "en": "The legs kept moving on the plate, you see.", "hl": ["거든요"]}, {"ko": "막상 먹어 보니까 생각보다 고소하고 맛있었어요.", "en": "But when I actually tried it, it was nuttier and tastier than I expected.", "hl": ["보니까"]}], "patterns": [{"name": "~았/었을 때", "exp": "When (something happened).", "ex_ko": "한국에 처음 왔을 때 모든 게 신기했어요.", "ex_en": "Everything was new when I first came to Korea.", "match": ["을 때", "었을 때", "았을 때"]}, {"name": "~거든요", "exp": "Explain the reason (you see…).", "ex_ko": "냄새가 정말 강했거든요.", "ex_en": "The smell was really strong, you see.", "match": ["거든요"]}, {"name": "~아/어 보니까", "exp": "What you found out after trying.", "ex_ko": "직접 만들어 보니까 생각보다 쉬웠어요.", "ex_en": "When I made it myself, it was easier than I thought.", "match": ["보니까", "보니"]}], "frames": [{"parts": ["처음 ", {"slot": true, "options": ["산낙지", "홍어", "번데기", "청국장"], "josa": "을/를", "ph": "…"}, " 먹었을 때 정말 놀랐어요."], "en": "I was really surprised the first time I ate ___."}, {"parts": [{"slot": true, "options": ["냄새가 너무 강했거든요", "모양이 신기했거든요", "맛이 생각과 완전히 달랐거든요"], "josa": null, "ph": "…"}, "."], "en": "Because ___."}, {"parts": ["막상 먹어 보니까 ", {"slot": true, "options": ["생각보다 맛있었어요", "조금 힘들었어요", "계속 생각났어요"], "josa": null, "ph": "…"}, "."], "en": "When I actually tried it, ___."}], "words": ["처음", "놀랐", "냄새", "생각보다", "맛있"], "checklist": [{"label": "Name the food", "any": ["처음", "먹었을 때", "먹어 봤"]}, {"label": "Say why it surprised you", "any": ["거든요", "@reason", "때문에"]}, {"label": "Say how it was after trying", "any": ["보니까", "생각보다", "먹어 보"]}], "model_answer": "처음 청국장을 먹었을 때 정말 놀랐어요. 끓이기 시작하자마자 집 안에 냄새가 가득 찼거든요. 그런데 막상 먹어 보니까 생각보다 구수하고 맛있었어요. 지금은 추운 날이면 가끔 생각나는 음식이 됐어요."}'::jsonb, true)
  on conflict (topic_ko, level) do update set content = excluded.content, reviewed = true, updated_at = now();
